function bindMissingCoverSearches(root=document){if(!window.fetch)return;const items=[...(root.matches?.('[data-cover-lookup]')?[root]:[]),...(root.querySelectorAll?.('[data-cover-lookup]')||[])];for(const item of items){if(item.dataset.coverRequested)continue;item.dataset.coverRequested='1';if(item.dataset.coverLocal==='true'&&Number(item.dataset.coverBookId)>0){post({type:'loadBookCover',bookId:Number(item.dataset.coverBookId)});continue}const lookup=item.dataset.coverLookup||'',parts=lookup.split('\n'),title=parts[0]?.trim(),author=parts.slice(1).join(' ').trim();if(!title)continue;const key=`${title.toLocaleLowerCase()}|${author.toLocaleLowerCase()}`;const apply=url=>{if(!url||!item.isConnected)return;const img=new Image();img.alt=`Cover of ${title}`;img.dataset.coverAuthor=author;img.loading='lazy';img.onload=()=>{if(item.isConnected)item.replaceWith(img)};img.onerror=()=>{coverSearchCache.set(key,null)};img.src=url};const cached=coverSearchCache.get(key);if(typeof cached==='string'){apply(cached);continue}if(cached===null)continue;if(cached instanceof Promise){cached.then(apply);continue}const search=async()=>{try{const params=new URLSearchParams({title,limit:'3',fields:'cover_i,title,author_name'});if(author)params.set('author',author);const response=await fetch(`https://openlibrary.org/search.json?${params}`);if(!response.ok)throw new Error('Cover lookup unavailable');const data=await response.json();const doc=(data.docs||[]).find(x=>x.cover_i);const url=doc?`https://covers.openlibrary.org/b/id/${Number(doc.cover_i)}-M.jpg`:null;coverSearchCache.set(key,url);apply(url)}catch{coverSearchCache.set(key,null)}};let startSearch;const request=new Promise(resolve=>{startSearch=()=>queueCoverSearch(()=>search().then(resolve))});coverSearchCache.set(key,request);request.then(apply);if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(x=>x.isIntersecting)){observer.disconnect();startSearch()}},{rootMargin:'240px'});observer.observe(item)}else startSearch()}}
