function sameWork(local,external){const lt=coreBookTitle(local.title),ht=coreBookTitle(external.title),la=normalizedAuthors(local.authors).split(' ').filter(Boolean).sort().join(' '),ha=normalizedAuthors(external.author||external.authors).split(' ').filter(Boolean).sort().join(' ');if(!lt||!ht)return false;const identifiers=x=>new Set(String(x.identifiers||'').toLocaleLowerCase().match(/(?:isbn|uuid|hardcover|goodreads)\s*[:=]\s*[\w-]+/g)||[]),li=identifiers(local),hi=identifiers(external);if([...li].some(x=>hi.has(x)))return true;if(lt===ht)return !!(la&&ha&&la===ha)||(lt.split(' ').length>=5&&lt.length>=28&&(!la||!ha));if(!la||!ha)return false;const at=new Set(la.split(' ')),bt=new Set(ha.split(' ')),authorOverlap=[...at].filter(x=>bt.has(x)).length/Math.max(at.size,bt.size);if(authorOverlap<0.8)return false;const a=new Set(lt.split(' ')),b=new Set(ht.split(' ')),overlap=[...a].filter(x=>b.has(x)).length/Math.max(a.size,b.size);return Math.min(a.size,b.size)>=4&&overlap>=0.9}
