function renderUnmatched(){const section=document.getElementById('unmatchedSection'),list=booksData?.unmatchedProgress||[];section.hidden=!list.length;document.getElementById('unmatchedBooks').innerHTML=list.map(item=>{const pct=Math.round(Number(item.percentage||0)*100),suggested=Number(item.suggestedBookId||0);const options=(booksData.allBooks||[]).map(b=>`<option value="${Number(b.id)}" ${Number(b.id)===suggested?'selected':''}>${esc(b.title)} · ${esc(b.authors)}</option>`).join('');const noMetadata=!item.title&&!item.author&&!item.filename;const identity=item.title?`Possible title: ${esc(item.title)}${item.author?` · ${esc(item.author)}`:''}${suggested?` · suggested match ${Math.round(Number(item.suggestedConfidence||0)*100)}%`:''}`:item.filename?`Reader book: ${esc(cleanBookLabel(item.filename))} · Shelf will retry matching.`:noMetadata&&String(item.device||'').toLowerCase().includes('readest')?'Readest sent a file ID without book details. Enable “Send Document Metadata” in its KOReader Sync settings and sync again; Shelf retries automatically.':'This reader did not send the book title yet. Shelf will match it when title details arrive.';return `<article class="unmatched-card"><div class="unmatched-summary"><b>${esc(item.device||'Unknown device')} · ${pct}%</b><small>${identity}</small><small>${item.timestamp?new Date(Number(item.timestamp)*1000).toLocaleString():'Time unavailable'}</small></div><div class="unmatched-action"><select aria-label="Match sync position to a Calibre book" id="match-${esc(item.document)}"><option value="">Choose the matching book…</option>${options}</select><button class="small-btn" onclick="matchProgress('${esc(item.document)}')">Link book</button></div></article>`}).join('')}
function renderAutoMatchReview(){const section=document.getElementById('autoMatchReviewSection'),list=booksData?.reviewProgressMatches||[];section.hidden=!list.length;document.getElementById('autoMatchReview').innerHTML=list.map(item=>{const options=(booksData.allBooks||[]).map(b=>`<option value="${Number(b.id)}" ${Number(b.id)===Number(item.bookId)?'selected':''}>${esc(b.title)} · ${esc(b.authors)}</option>`).join('');const evidence=[item.sourceTitle,item.sourceAuthor,item.sourceFilename].filter(Boolean).join(' · ')||'Limited device metadata';return `<article class="unmatched-card"><div class="unmatched-summary"><b>${Math.round(Number(item.confidence||0)*100)}% match · ${esc(item.bookTitle||'Suggested book')}</b><small>${esc(item.bookAuthor||'Unknown author')}</small><small>Device identity: ${esc(evidence)}</small></div><div class="unmatched-action"><select aria-label="Correct the suggested Calibre book" id="review-match-${esc(item.document)}">${options}</select><button class="small-btn" onclick="matchProgress('${esc(item.document)}',true)">Confirm / change</button></div></article>`}).join('')}
