function renderLibraryHealth(books){const root=document.getElementById('libraryHealth');if(!root)return;const noCover=books.filter(b=>!b.coverPath),noAuthor=books.filter(b=>!b.authors||/^unknown author$/i.test(b.authors)),noFile=books.filter(b=>!String(b.formats||'').trim());const seen=new Map(),dupes=[];for(const b of books){const key=`${String(b.title||'').normalize('NFKC').trim().toLocaleLowerCase()}|${String(b.authors||'').normalize('NFKC').trim().toLocaleLowerCase()}`;if(seen.has(key))dupes.push(b);else seen.set(key,b)}const issues=noCover.length+noAuthor.length+dupes.length;root.hidden=false;root.innerHTML=`<div class="library-health-head"><div><b>Library health</b><small>${issues?`${issues.toLocaleString()} items need a quick look`:'No basic metadata gaps found'} · instant local check</small></div><span class="health-indicator ${issues?'attention':'healthy'}">${issues?'Review':'Healthy'}</span></div><div class="health-chips">${[[noCover,'Missing covers'],[noAuthor,'Missing authors'],[noFile,'Metadata-only'],[dupes,'Possible duplicates']].map(([items,label])=>`<button class="health-chip" ${items.length?`onclick="filterLibraryHealth('${label}')"`:''}><b>${items.length.toLocaleString()}</b>${label}</button>`).join('')}</div><small>Read-only check. Shelf groups possible duplicates for browsing but never deletes or edits Calibre records.</small>`}
function enableCalibreFullText(){const status=document.getElementById('fullTextStatus');if(status)status.textContent='Asking Calibre to start its low-resource index…';post({type:'calibreFullText',action:'enable'})}
function searchCalibreFullText(){const query=document.getElementById('fullTextQuery')?.value?.trim();if(!query)return;const status=document.getElementById('fullTextStatus');if(status)status.textContent='Searching book text…';post({type:'calibreFullText',action:'search',query})}
function renderFullTextResult(x){const status=document.getElementById('fullTextStatus'),root=document.getElementById('fullTextResults');if(!status||!root)return;status.textContent=x.message||(!x.ok?'Calibre could not complete this request.':x.action==='search'?'Search complete.':'Index status checked.');if(x.action!=='search'){root.hidden=true;return}root.hidden=false;const ids=new Set();const walk=v=>{if(Array.isArray(v)){v.forEach(walk);return}if(v&&typeof v==='object'){for(const [k,val] of Object.entries(v)){if(['book_id','bookId','id'].includes(k)&&Number.isInteger(Number(val)))ids.add(Number(val));else walk(val)}}};walk(x.results);const known=(booksData?.allBooks||[]).filter(b=>ids.has(Number(b.id)));root.innerHTML=known.length?known.map(b=>`<div class="fulltext-hit"><div><b>${esc(b.title)}</b><small>${esc(b.authors||'')}</small></div><button class="small-btn" onclick="readBook(${Number(b.id)})">Open book</button></div>`).join(''):`<p>${ids.size?`${ids.size} matches found, but Calibre returned no matching book records.`:'No matches were found.'}</p>`}
window.fullTextResult=renderFullTextResult;
function filterLibraryHealth(label){bookSearch='';const input=document.getElementById('librarySearch');if(input)input.value='';bookShelfFilter='all';const candidates=unifiedBooks();let ids=new Set();if(label==='Missing covers')ids=new Set(candidates.filter(b=>!b.coverPath&&!b.coverData&&!b.coverURL).map(b=>Number(b.id)));else if(label==='Missing authors')ids=new Set(candidates.filter(b=>!b.authors||/^unknown author$/i.test(b.authors)).map(b=>Number(b.id)));else if(label==='Metadata-only')ids=new Set(candidates.filter(b=>!String(b.formats||'').trim()).map(b=>Number(b.id)));else if(label==='Possible duplicates'){const raw=booksData?.allBooks||[],counts=new Map();for(const b of raw){const k=`${String(b.title||'').normalize('NFKC').trim().toLocaleLowerCase()}|${String(b.authors||'').normalize('NFKC').trim().toLocaleLowerCase()}`;counts.set(k,(counts.get(k)||0)+1)}ids=new Set(raw.filter(b=>counts.get(`${String(b.title||'').normalize('NFKC').trim().toLocaleLowerCase()}|${String(b.authors||'').normalize('NFKC').trim().toLocaleLowerCase()}`)>1).map(b=>Number(b.id)))};healthFilterIds=ids;renderAllBooks();document.getElementById('allBooks')?.scrollIntoView({behavior:'smooth',block:'start'});}
function loadHardcoverShelf(force=false){if(!force&&hardcoverShelfDataCache)return;const notice=document.getElementById('hardcoverSyncNotice');if(notice){notice.hidden=false;notice.textContent='Loading audiobook and Hardcover status…'}post({type:'loadHardcoverShelf'})}
let hardcoverShelfDataCache=null;
function renderBookPlayerShelf(){const root=document.getElementById('bookPlayerReading');if(!root)return;const books=hardcoverShelfDataCache?.books||[];const summary=document.getElementById('audiobookStatusSummary');if(summary)summary.textContent=hardcoverShelfDataCache?`${books.length} title${books.length===1?'':'s'} currently reading on Hardcover · refreshed ${new Date(hardcoverShelfDataCache.loadedAt||Date.now()).toLocaleTimeString()}`:'Waiting for the Hardcover connection';if(!hardcoverShelfDataCache){root.innerHTML='<div class="empty-books">Connect Hardcover in Connections to show BookPlayer reading status here.</div>';return}root.innerHTML=books.length?books.map(book=>{const title=book.title||'Untitled audiobook',author=book.author||book.authors||'Author not provided',cover=bookCover({title,authors:author,coverURL:book.coverURL}),progressSeconds=Number(book.progress_seconds??book.progressSeconds),durationSeconds=Number(book.duration_seconds??book.durationSeconds),hasAudioProgress=Number.isFinite(progressSeconds)&&Number.isFinite(durationSeconds)&&durationSeconds>0,pct=hasAudioProgress?Math.max(0,Math.min(100,Math.round(progressSeconds/durationSeconds*100))):null,position=hasAudioProgress?`${formatBookPlayerTime(progressSeconds)} of ${formatBookPlayerTime(durationSeconds)} listened`:'';return `<article class="reading-book audiobook-book"><div class="reading-cover">${cover}</div><div class="reading-info"><span class="eyebrow audiobook-label">CURRENTLY READING · HARDCOVER</span><h4>${esc(title)}</h4><p>${esc(author)}</p>${pct===null?'<small>Reading status synced · audio position unavailable</small>':`<div class="progress-track"><i style="width:${pct}%"></i></div><small>${pct}% listened · ${esc(position)}</small>`}<button class="small-btn" onclick="openBookLink('https://hardcover.app/')">View on Hardcover ↗</button></div></article>`}).join(''):'<div class="empty-books"><div class="empty-icon">♫</div><div><b>No active audiobook status yet</b><p>When BookPlayer marks a title as currently reading on the same Hardcover account connected to Shelf, it will appear here.</p></div></div>'}
function ensureAppleBooksShelf(){if(document.getElementById('appleBooksShelf'))return;const anchor=document.getElementById('bookPlayerReading');if(!anchor)return;const section=document.createElement('section');section.id='appleBooksShelf';section.className='apple-books-shelf';section.innerHTML='<div class="section-head audiobook-heading"><div><h3>Apple Books · reading on this Mac</h3><p id="appleBooksSummary">Checking for a local Apple Books library…</p></div><button class="small-btn" onclick="post({type:\'openAppleBooks\'})">Open Apple Books</button></div><div id="appleBooksReading" class="reading-grid audiobook-grid"></div><div class="book-source">Read-only progress from books synced to this Mac. Catalog import adds metadata entries to Calibre; protected Apple Books files stay in Books.</div>';anchor.insertAdjacentElement('afterend',section)}
function loadAppleBooks(force=false){if(appleBooksData&&!force){renderAllBooks();return}post({type:'loadAppleBooks'})}
function renderAppleBooks(){ensureAppleBooksShelf();const root=document.getElementById('appleBooksReading'),summary=document.getElementById('appleBooksSummary'),statusBox=document.getElementById('appleBooksSyncStatus');if(!root||!summary)return;const status=appleBooksData?.status,books=appleBooksData?.books||[],reading=books.filter(book=>Number(book.progress)>0&&!book.finished);if(statusBox){statusBox.hidden=false;statusBox.textContent=status==='connected'?`Apple Books · ${books.length} titles available on this Mac`:`Apple Books · ${status==='permission_required'?'allow Shelf in Full Disk Access to read progress':status==='not_found'?'waiting for Books to sync to this Mac':'checking local access'}`}if(!appleBooksData){summary.textContent='Checking for a local Apple Books library…';root.innerHTML='<div class="empty-books">Checking this Mac for Apple Books progress…</div>';return}if(status==='permission_required'){summary.textContent='macOS is protecting the Apple Books library';root.innerHTML='<div class="empty-books"><div><b>Allow Shelf to read Apple Books progress</b><p>In System Settings → Privacy &amp; Security → Full Disk Access, enable Shelf, then quit and reopen it. Shelf reads the Books database without changing it.</p><button class="small-btn" onclick="post({type:\'openFullDiskAccessSettings\'})">Open Full Disk Access settings</button></div></div>';return}if(status==='not_found'){summary.textContent='No synced Apple Books library found on this Mac';root.innerHTML='<div class="empty-books"><div><b>Apple Books has not synced its library here yet</b><p>Open Apple Books on this Mac and make sure Books is enabled in iCloud. Shelf will check again automatically.</p></div></div>';return}if(status!=='connected'){summary.textContent='Apple Books data is currently unavailable';root.innerHTML='<div class="empty-books">The local Books library is unavailable or its format changed. Shelf will retry automatically.</div>';return}summary.textContent=`${books.length} books and audiobooks found · ${reading.length} currently in progress · refreshed ${new Date().toLocaleTimeString()}`;root.innerHTML=reading.length?reading.slice(0,12).map(book=>{const audio=book.mediaType==='audiobook',pct=Math.round(Math.max(0,Math.min(1,Number(book.progress)||0))*100),cover=bookCover({title:book.title,authors:book.author,coverURL:book.coverURL});return `<article class="reading-book audiobook-book"><div class="reading-cover">${cover}</div><div class="reading-info"><span class="eyebrow audiobook-label">APPLE BOOKS · ${audio?'AUDIOBOOK':'BOOK'}${book.finished?' · FINISHED':''}</span><h4>${esc(book.title)}</h4><p>${esc(book.author||'Author not provided')}</p><div class="progress-track"><i style="width:${pct}%"></i></div><small>${pct}% ${audio?'listened':'read'}${audio&&book.duration?` · ${formatBookPlayerTime(book.duration)} total`:''}</small>${book.lastEngaged?`<small>Last active ${esc(new Date(book.lastEngaged).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))}</small>`:''}</div></article>`}).join(''):'<div class="empty-books">No Apple Books titles currently have reading progress.</div>'}
