function formatBookPlayerTime(value){const total=Math.max(0,Math.floor(value)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60);return hours?`${hours}h ${minutes}m`:`${minutes}m`}
function renderHardcoverShelf(d){hardcoverShelfDataCache=d;const notice=document.getElementById('hardcoverSyncNotice');if(notice){notice.hidden=true;notice.textContent=''}renderAllBooks();renderBookPlayerShelf();if(activePage==='statistics')renderStatistics()}
function renderStatistics(){const cards=document.getElementById('readingStatsCards');if(!cards)return;const local=booksData?.allBooks||[],tracked=unifiedBooks(),reading=tracked.filter(b=>{const p=Number(b.progress??b.appleBooks?.progress??b.hardcover?.progress??0);return p>0&&p<.97&&!b.finished}),finished=tracked.filter(b=>b.finished||b.appleBooks?.finished||Number(b.progress??b.appleBooks?.progress??0)>=.97),events=data?.syncActivity||[],connectors=(data?.connectors||[]).filter(x=>Number(x.enabled)&&x.status==='ok'),weekAgo=Date.now()-7*86400000,recent=events.filter(e=>new Date(e.date).getTime()>=weekAgo);document.getElementById('statsTrackedBooks').textContent=tracked.length.toLocaleString();const values=[['IN PROGRESS',reading.length,'Across formats and connected sources'],['FINISHED',finished.length,'Marked complete at 97% or more'],['AUDIOBOOKS',hardcoverShelfDataCache?.books?.length||0,'Audiobook titles from connected services'],['SYNC UPDATES · 7 DAYS',recent.length,'Successful updates from reader logs'],['CONNECTED SOURCES',connectors.length+(data?.readwiseConnected?1:0),'Live provider APIs']];cards.innerHTML=values.map(([label,value,caption])=>`<div class="stat"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(caption)}</small></div>`).join('');const days=Array.from({length:7},(_,i)=>{const day=new Date();day.setHours(0,0,0,0);day.setDate(day.getDate()-(6-i));const key=day.toLocaleDateString();return{key,label:day.toLocaleDateString(undefined,{weekday:'short'}),count:events.filter(e=>new Date(e.date).toLocaleDateString()===key).length}}),max=Math.max(1,...days.map(x=>x.count));document.getElementById('syncWeekChart').innerHTML=days.map(x=>`<div class="sync-day"><div class="sync-bar-wrap"><i style="height:${Math.max(x.count?8:2,Math.round(x.count/max*100))}%" title="${x.count} sync updates"></i></div><b>${x.count}</b><small>${esc(x.label)}</small></div>`).join('');const booksById=new Map(local.map(b=>[Number(b.id),b]));document.getElementById('readingActivity').innerHTML=events.slice(0,18).map(e=>{const book=booksById.get(Number(e.bookId)),when=e.date?new Date(e.date).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Time unavailable';return `<div class="event"><i class="event-dot healthy"></i><div class="event-body"><p><b>${esc(e.device||'Reader')}</b> · ${esc(book?.title||'Book progress updated')} · ${Math.round(Number(e.progress||0)*100)}% complete</p><small>${esc(when)}</small></div></div>`}).join('')||'<div class="event"><div class="event-body"><p>No successful reader syncs have been logged yet.</p><small>Updates appear automatically after KOReader or another connected reader syncs.</small></div></div>';const sources=(data?.items||[]).filter(x=>x.category==='Service'&&['calibre','kosync','crosspoint'].includes(x.id)).map(x=>[x.name,x.summary,x.state]);sources.push(['Readwise Reader',data?.readwiseConnected?'Access token saved locally':'Not connected',data?.readwiseConnected?'healthy':'optional']);const hardCover=(data?.connectors||[]).find(x=>x.id==='hardcover'),hStatus=!hardCover?'optional':!Number(hardCover.enabled)?'optional':hardCover.status==='ok'?'healthy':'warning';sources.push(['Hardcover',hardCover?.status==='ok'?`${hardcoverShelfDataCache?.books?.length||0} currently reading titles available`:'Not connected or unavailable',hStatus]);sources.push(...connectors.filter(x=>x.id!=='hardcover').map(x=>[x.id,`${Number(x.pending||0)} queued · ${Number(x.failed||0)} failed`,x.status==='ok'?'healthy':'warning']));document.getElementById('readingSources').innerHTML=sources.map(([name,summary,state])=>`<article class="connector-card"><div class="connector-top"><div class="service-icon">↔</div>${badge(state)}</div><h4>${esc(name)}</h4><p>${esc(summary)}</p></article>`).join('')}
function loadDiscovery(period,force=false){activePeriod=period;if(discoveryCache[period]&&!force){renderDiscovery(discoveryCache[period]);return}document.getElementById('discoveryBooks').innerHTML='<div class="empty-books">Searching Hardcover…</div>';document.getElementById('discoveryBasis').textContent='Loading Hardcover catalog…';post({type:'loadDiscovery',period})}
function searchHardcover(){const q=document.getElementById('hardcoverSearch')?.value.trim();if(!q)return;document.getElementById('discoveryBooks').innerHTML='<div class="empty-books">Searching Hardcover…</div>';post({type:'searchHardcover',query:q})}
function discoveryCard(b){const cover=b.coverURL?`<img src="${esc(b.coverURL)}" alt="Cover of ${esc(b.title)}" loading="lazy" onerror="this.nextElementSibling.classList.remove('cover-hidden')"><div class="cover-fallback cover-hidden"><span>▤</span><small>${esc(b.title)}</small></div>`:`<div class="cover-fallback"><span>▤</span><small>${esc(b.title)}</small></div>`;const url=`https://hardcover.app/books/${encodeURIComponent(b.slug||b.externalId||'')}`;return `<article class="discover-book"><div class="discover-cover">${cover}</div><div class="discover-meta"><h3>${esc(b.title)}</h3><p>${esc(b.author||b.authors||'Author unknown')}</p><div class="discover-actions"><button class="small-btn" onclick="openBookLink('${url}')">Open on Hardcover</button></div></div></article>`}
function renderDiscovery(d){if(d.period)discoveryCache[d.period]=d;activePeriod=d.period||activePeriod;document.querySelectorAll('.period-tab').forEach(x=>x.classList.toggle('active',x.dataset.period===activePeriod));document.getElementById('discoveryBasis').textContent=d.basis||'Hardcover catalog';document.getElementById('discoveryUpdated').textContent=d.loadedAt?'Updated '+new Date(d.loadedAt).toLocaleTimeString():'';document.getElementById('discoveryBooks').innerHTML=(d.books||[]).map(discoveryCard).join('')||'<div class="empty-books">No titles are available right now. Shelf checks again automatically.</div>'}
function action(id){post({type:'action',id})}function readBook(bookId){post({type:'openBook',bookId:Number(bookId)})}function matchProgress(docHash,review=false){const select=document.getElementById(`${review?'review-match-':'match-'}${docHash}`);if(!select?.value){dashboardNotice({message:'Choose a book first.'});return}post({type:'saveProgressMatch',document:docHash,bookId:Number(select.value)})}function exportDiagnostics(){post({type:'exportDiagnostics',additionalText:document.getElementById('extraDiagnosticText')?.value||''})}function copy(id){copyText(document.getElementById(id).textContent)}function copyText(text){post({type:'copy',text})}function openBookLink(url){post({type:'openBookLink',url})}
function saveReadwiseKey(){const input=document.getElementById('readwiseTokenInput'),token=input?.value?.trim();if(!token){dashboardNotice({message:'Paste your Readwise access token first.'});input?.focus();return}post({type:'saveReadwiseReaderToken',token})}
window.updateDashboard=x=>{data=x;render()};
window.readwiseTokenSaved=()=>{const input=document.getElementById('readwiseTokenInput');if(input)input.value='';if(data){data.readwiseConnected=true;renderIntegrations(data.connectors||[]);renderStatistics()}};
window.dashboardNotice=x=>{const t=document.getElementById('toast');t.textContent=x.message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4200)};
window.bookshelfData=x=>{renderBooks(x);renderStatistics()};
window.hardcoverShelfData=x=>{renderHardcoverShelf(x);renderStatistics()};
window.hardcoverShelfError=x=>{hardcoverShelfDataCache=null;const el=document.getElementById('hardcoverSyncNotice');if(el){el.hidden=false;el.innerHTML=`${esc(x.message)} <button class="small-btn" onclick="post({type:'openCrossPointSettings'})">Open Connections</button>`}renderAllBooks();renderStatistics()};
window.bookshelfError=x=>{const grid=document.getElementById('allBooks');if(grid)grid.innerHTML=`<div class="empty-books">${esc(x.message)}</div>`};
window.discoveryData=renderDiscovery;
window.discoveryError=x=>{document.getElementById('discoveryBooks').innerHTML=`<div class="empty-books">${esc(x.message)}</div>`;document.getElementById('discoveryBasis').textContent='Hardcover is temporarily unavailable'};
window.readerNotice=x=>dashboardNotice({message:x.message||'Reader update'});
window.readerProgressUpdated=x=>{if(booksData?.allBooks){const book=booksData.allBooks.find(b=>Number(b.id)===Number(x.bookId));if(book){book.progress=Number(x.percentage);book.finished=book.manuallyFinished||book.progress>=.97;booksData.finished=booksData.allBooks.filter(b=>b.finished);booksData.reading=booksData.allBooks.filter(b=>b.progress>0&&!b.finished);renderBooks(booksData);renderStatistics()}}};
function setBookFinished(bookId,finished){post({type:'setBookFinished',bookId:Number(bookId),finished:!!finished})}
post({type:'loadSetup'});loadBooks();loadHardcoverShelf();loadAppleBooks();
